export const dedupe = values => {
  if (!values || values.length === 0) return [];

  // Track the last position and value for each id
  const lastPos = new Map();

  // First pass: find the last occurrence of each id
  for (let i = values.length - 1; i >= 0; i--) {
    const id = values[i].id;
    if (!lastPos.has(id)) {
      lastPos.set(id, i);
    }
  }

  // Second pass: collect the last occurrences in order of their positions
  const result = [];
  for (let i = 0; i < values.length; i++) {
    if (i === lastPos.get(values[i].id)) {
      result.push(values[i]);
    }
  }

  return result;
};

export const isInside = (root, candidate) => {
  // Normalize both paths by splitting on '/' and handling dot segments
  const normalizePath = (path) => {
    const parts = path.split('/').filter((p) => p !== '');

    // Handle .. segments (go up one level)
    let stack = [...parts];
    for (let i = stack.length - 1; i >= 0; i--) {
      if (stack[i] === '..') {
        stack.splice(i, 1);
      }
    }

    // Handle . segments (current directory) - they are empty after normalization
    return stack.filter((p) => p !== '.');
  };

  const rootParts = normalizePath(root);
  const candidateParts = normalizePath(candidate);

  // Reject if candidate is not an absolute POSIX path (no leading '/')
  if (!candidate.startsWith('/')) {
    return false;
  }

  // Root must be an absolute path starting with '/'
  if (!root.startsWith('/')) {
    return false;
  }

  // Candidate must have at least as many parts as root
  if (candidateParts.length < rootParts.length) {
    return false;
  }

  // Check if candidate starts with root and has additional segments
  for (let i = 0; i < rootParts.length; i++) {
    if (rootParts[i] !== candidateParts[i]) {
      return false;
    }
  }

  // Candidate must be either the root itself or a descendant
  // If it's exactly the same, that's allowed
  if (candidateParts.length === rootParts.length) {
    return true;
  }

  // Check that candidate has additional segments after root
  for (let i = rootParts.length; i < candidateParts.length; i++) {
    if (!candidateParts[i]) {
      return false;
    }
  }

  return true;
};

export const dedupe = (records) => {
  if (!records || records.length === 0) {
    return [];
  }

  // Track the last index of each id and the record at that position
  const lastOccurrence = new Map();

  // First pass: find the last occurrence of each id
  for (let i = 0; i < records.length; i++) {
    const record = records[i];
    const id = record.id;
    if (!lastOccurrence.has(id)) {
      lastOccurrence.set(id, i);
    } else {
      // Update to the latest position
      lastOccurrence.set(id, i);
    }
  }

  // Second pass: build result with records in order of their last occurrence positions
  const result = [];
  const usedIds = new Set();

  for (let i = 0; i < records.length; i++) {
    const record = records[i];
    const id = record.id;

    // Only include if this is the last occurrence of this id
    if (lastOccurrence.get(id) === i && !usedIds.has(id)) {
      result.push(record);
      usedIds.add(id);
    }
  }

  return result;
};

export const isInside = (root, candidate) => {
  // Normalize paths by resolving dot segments manually for absolute POSIX paths
  // For absolute paths: split by '/', filter out '.' and resolve '..'
  const normalizePath = (path) => {
    if (!path.startsWith('/')) return path; // Not an absolute path

    const parts = path.split('/').filter(p => p !== '');
    let result = [];

    for (const part of parts) {
      if (part === '.') continue; // Skip current directory
      if (part === '..') {
        // Go up one level if possible
        if (result.length > 0 && result[result.length - 1] !== '..') {
          result.pop();
        }
      } else {
        result.push(part);
      }
    }

    return '/' + result.join('/');
  };

  const normalizedRoot = normalizePath(root);
  const normalizedCandidate = normalizePath(candidate);

  // For absolute paths, root must be a prefix of candidate with proper path separator
  // Accept the root itself or any descendant
  // Special case: if root is just "/", everything is inside it
  if (normalizedRoot === '/') return true;

  return normalizedCandidate === normalizedRoot || 
         normalizedCandidate.startsWith(normalizedRoot + '/');
};

export const total = items => items.reduce((sum,item)=>{
  if (item.enabled === true) {
    return sum + item.amount;
  }
  return sum;
},0);
